// ============================================================
// NORMALIZE EVOLUTION API MESSAGE
// ============================================================

const body = $input.first().json.body;
const data = body.data || {};
const message = data.message || {};

// Determine content type and extract content
let contentType = 'unknown';
let content = '';

if (message.conversation) {
  contentType = 'text';
  content = message.conversation;
} else if (message.extendedTextMessage?.text) {
  contentType = 'text';
  content = message.extendedTextMessage.text;
} else if (message.audioMessage) {
  contentType = 'audio';
} else if (message.imageMessage) {
  contentType = 'image';
  content = message.imageMessage.caption || '';
}

// Normalize phone
let phone = data.key?.remoteJid || '';
phone = phone.replace('@s.whatsapp.net', '').replace(/^549/, '54');

return {
  // Instance info (for sending responses)
  instance: {
    server_url: body.server_url,
    instance_name: body.instance,
    apikey: body.apikey
  },

  // Message details
  message: {
    id: data.key?.id,
    phone: phone,
    raw_jid: data.key?.remoteJid,
    content_type: contentType,
    content: content,
    timestamp: body.date_time || new Date().toISOString()
  },

  // User info
  user: {
    phone: phone,
    name: data.pushName || null
  },

  source: 'whatsapp',
  channel: 'evolution'
};

// ============================================================
// PREPARE FOR AI PROCESSING
// Combines messages and extracts lead info
// ============================================================

const messages = $input.first().json.messages || [];
const normalizedData = $('Normalize Message').first().json;

// Combine all messages
const fullMessage = Array.isArray(messages) ? messages.join('\n') : String(messages);

// Extract email if present
const emailMatch = fullMessage.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);
const email = emailMatch ? emailMatch[0] : null;

// Extract name if mentioned
let name = normalizedData.user?.name || null;
const nameMatch = fullMessage.match(/(?:me llamo|soy|mi nombre es)\s+([A-Za-zÁÉÍÓÚÜÑáéíóúüñ\s]{2,40})/i);
if (nameMatch) name = nameMatch[1].trim();

return {
  phone: normalizedData.message?.phone,
  message: fullMessage,
  instance: normalizedData.instance,
  user: {
    phone: normalizedData.message?.phone,
    name: name,
    email: email
  },
  source: 'whatsapp',
  channel: 'evolution'
};

// ============================================================
// BUILD CLIENT CONTEXT FOR AI
// ============================================================

const lead = $input.first().json;
const msgData = $('Prepare for Processing').first().json;

let context = `📞 Teléfono: ${lead.phone}`;
if (lead.name) context += `\n👤 Nombre: ${lead.name}`;
if (lead.email) context += `\n📧 Email: ${lead.email}`;
if (lead.temperature && lead.temperature !== 'cold') context += `\n🌡️ Temperatura: ${lead.temperature}`;
if (lead.score) context += `\n📊 Score: ${lead.score}`;
if (lead.intent) context += `\n🎯 Interés: ${lead.intent}`;
if (lead.preferred_zones?.length) context += `\n📍 Zonas: ${lead.preferred_zones.join(', ')}`;
if (lead.budget_max) context += `\n💰 Presupuesto: ${lead.budget_max}`;

return {
  ...msgData,
  lead_id: lead.id,
  lead_crm_id: lead.crm_id,
  client_context: context,
  client: lead
};

// ============================================================
// PARSE PROPERTY FILTERS FROM MESSAGE
// ============================================================

const data = $input.first().json;
const text = (data.message || '').toLowerCase();

// Operation type
let operacion = null;
if (/(alquiler|alquilar|renta|arriendo)/.test(text)) operacion = 'alquiler';
if (/(venta|comprar|compra)/.test(text)) operacion = 'venta';

// Bedrooms
let dormitorios = null;
const dormMatch = text.match(/(\d+)\s*(?:hab|habitaci[oó]n|habitaciones|dorm|dormitorio|dormitorios|amb|ambientes)/);
if (dormMatch) dormitorios = Number(dormMatch[1]);

// Max price
let precio_max = null;
const priceMatch = text.match(/(?:hasta|max|presupuesto|budget)?\s*(?:usd|us\$|\$)?\s*(\d+(?:[\.,]\d+)?)\s*([km])?/i);
if (priceMatch) {
  let n = Number(priceMatch[1].replace(',', '.'));
  const suffix = priceMatch[2]?.toLowerCase();
  if (suffix === 'k') n *= 1000;
  if (suffix === 'm') n *= 1000000;
  if (n > 1000) precio_max = Math.round(n);
}

// Search keywords
const searchText = data.message
  .replace(/\d+/g, ' ')
  .replace(/[^a-záéíóúüñ\s]/gi, ' ')
  .trim()
  .substring(0, 100);

return {
  ...data,
  filters: {
    operacion,
    dormitorios,
    precio_max,
    searchText
  }
};

// ============================================================
// BUILD PROPERTY CONTEXT FOR AI
// ============================================================

const properties = $input.all().map(i => i.json);
const prevData = $('Parse Property Filters').first().json;

if (!properties.length || !properties[0].crm_id) {
  return {
    ...prevData,
    property_context: '📭 No se encontraron inmuebles que coincidan. Pide más detalles al cliente.',
    properties: []
  };
}

const lines = properties.map((p, idx) => {
  const price = p.precio 
    ? `${p.moneda || 'USD'} ${p.precio.toLocaleString()}`
    : 'Consultar';
  const loc = [p.barrio, p.ciudad].filter(Boolean).join(', ');
  const feats = [
    p.dormitorios ? `${p.dormitorios} hab` : null,
    p.banos ? `${p.banos} baños` : null,
    p.m2 ? `${p.m2} m²` : null
  ].filter(Boolean).join(' · ');

  let line = `${idx + 1}. **${p.titulo || 'Inmueble'}**`;
  if (loc) line += ` - ${loc}`;
  line += `\n   💰 ${price}`;
  if (feats) line += ` | ${feats}`;
  if (p.url) line += `\n   🔗 ${p.url}`;

  return line;
});

return {
  ...prevData,
  property_context: lines.join('\n\n'),
  properties: properties
};
